CREATE TABLE IF NOT EXISTS v2_objects (kind TEXT NOT NULL, id TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(kind,id));
CREATE TABLE IF NOT EXISTS v2_tasks (id TEXT PRIMARY KEY, owner TEXT NOT NULL, pool TEXT NOT NULL, state TEXT NOT NULL, ready INTEGER NOT NULL, created DOUBLE PRECISION NOT NULL, deadline DOUBLE PRECISION NOT NULL, version INTEGER NOT NULL, body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS v2_dispatch ON v2_tasks(pool,state,ready,created,id);
CREATE INDEX IF NOT EXISTS v2_task_owner ON v2_tasks(owner,created,id);
CREATE TABLE IF NOT EXISTS v2_attempts (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES v2_tasks(id), node_id TEXT NOT NULL, slot INTEGER NOT NULL, active INTEGER NOT NULL, epoch INTEGER NOT NULL, body TEXT NOT NULL, UNIQUE(task_id,epoch));
CREATE UNIQUE INDEX IF NOT EXISTS v2_active_slot ON v2_attempts(node_id,slot) WHERE active=1;
CREATE TABLE IF NOT EXISTS v2_events (task_id TEXT NOT NULL REFERENCES v2_tasks(id), seq INTEGER NOT NULL, created DOUBLE PRECISION NOT NULL, body TEXT NOT NULL, PRIMARY KEY(task_id,seq));
CREATE TABLE IF NOT EXISTS v2_runner_events (attempt_id TEXT NOT NULL REFERENCES v2_attempts(id), seq INTEGER NOT NULL, hash TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(attempt_id,seq));
CREATE TABLE IF NOT EXISTS v2_idempotency (scope TEXT NOT NULL, key TEXT NOT NULL, hash TEXT NOT NULL, response TEXT NOT NULL, created DOUBLE PRECISION NOT NULL, PRIMARY KEY(scope,key));
CREATE TABLE IF NOT EXISTS v2_credentials (hash TEXT PRIMARY KEY, node_id TEXT NOT NULL, expires DOUBLE PRECISION NOT NULL, created DOUBLE PRECISION NOT NULL);
CREATE INDEX IF NOT EXISTS v2_credential_node ON v2_credentials(node_id);
CREATE TABLE IF NOT EXISTS v2_outbox (id TEXT PRIMARY KEY REFERENCES v2_tasks(id), status TEXT NOT NULL, created DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS v2_usage (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES v2_tasks(id), pool TEXT NOT NULL, status TEXT NOT NULL, created DOUBLE PRECISION NOT NULL, body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS v2_usage_pool ON v2_usage(pool,created);
CREATE TABLE IF NOT EXISTS v2_ledger (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES v2_usage(id), task_id TEXT NOT NULL REFERENCES v2_tasks(id), created DOUBLE PRECISION NOT NULL, body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS v2_ledger_task ON v2_ledger(task_id,created);
CREATE TABLE IF NOT EXISTS v2_artifacts (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES v2_tasks(id), status TEXT NOT NULL, created DOUBLE PRECISION NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS v2_deletions (task_id TEXT PRIMARY KEY REFERENCES v2_tasks(id), requested DOUBLE PRECISION NOT NULL, completed DOUBLE PRECISION, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS v2_audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, created DOUBLE PRECISION NOT NULL, body TEXT NOT NULL);
INSERT INTO schema_version(version) VALUES(2) ON CONFLICT(version) DO NOTHING;
